CREATE DATABASE IF NOT EXISTS ops_auth CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE ops_auth;
CREATE TABLE IF NOT EXISTS sys_user (id BIGINT NOT NULL AUTO_INCREMENT,username VARCHAR(64) NOT NULL,password VARCHAR(128) NOT NULL,display_name VARCHAR(64) NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'enable',create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted TINYINT NOT NULL DEFAULT 0,PRIMARY KEY(id),UNIQUE KEY uk_user_username(username)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS sys_role (id BIGINT NOT NULL AUTO_INCREMENT,code VARCHAR(64) NOT NULL,name VARCHAR(64) NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'enable',create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted TINYINT NOT NULL DEFAULT 0,PRIMARY KEY(id),UNIQUE KEY uk_role_code(code)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS sys_permission (id BIGINT NOT NULL AUTO_INCREMENT,code VARCHAR(128) NOT NULL,name VARCHAR(128) NOT NULL,type VARCHAR(16) NOT NULL DEFAULT 'API',path VARCHAR(255),method VARCHAR(16),status VARCHAR(16) NOT NULL DEFAULT 'enable',create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY uk_permission_code(code)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS sys_user_role (id BIGINT NOT NULL AUTO_INCREMENT,user_id BIGINT NOT NULL,role_id BIGINT NOT NULL,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY uk_user_role(user_id,role_id),KEY idx_user_role_role(role_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS sys_role_permission (id BIGINT NOT NULL AUTO_INCREMENT,role_id BIGINT NOT NULL,permission_id BIGINT NOT NULL,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY uk_role_permission(role_id,permission_id),KEY idx_role_permission_permission(permission_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS auth_refresh_token (id BIGINT NOT NULL AUTO_INCREMENT,token_id CHAR(36) NOT NULL,user_id BIGINT NOT NULL,token_hash CHAR(64) NOT NULL,expire_time DATETIME NOT NULL,revoked TINYINT NOT NULL DEFAULT 0,revoke_time DATETIME,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY uk_refresh_hash(token_hash),KEY idx_refresh_user_status(user_id,revoked,expire_time)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
